fn count_under_over(nums: &Vec<Int>, cutoff: Int) -> Tuple<Int, Int> {
    let mut under = 0
    let mut over = 0
    for num in nums {
        if num < cutoff {
            under = under + 1
        } else {
            over = over + 1
        }
    }
    Tuple(under, over)
}

