struct Rectangle { width: Int, height: Int }

fn area(r: Rectangle) -> Int {
    r.width * r.height
}

fn perimeter(r: Rectangle) -> Int {
    2 * (r.width + r.height)
}

fn main() {
    let r = Rectangle { width: 9, height: 3 }
    print(area(r))
    print(perimeter(r))
}

